import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { productAPI } from '../services/api';
import ProductCard from '../components/ProductCard';

const CATEGORIES = [
  { id: '', label: 'All Products', emoji: '🛒' },
  { id: 'meat-fish', label: 'Meat & Fish', emoji: '🥩' },
  { id: 'vegetables', label: 'Vegetables', emoji: '🥦' },
  { id: 'dairy-eggs', label: 'Dairy & Eggs', emoji: '🥛' },
  { id: 'oils-ghee', label: 'Oils & Ghee', emoji: '🫙' },
  { id: 'millets-groceries', label: 'Millets & Groceries', emoji: '🌾' },
  { id: 'masalas', label: 'Masalas', emoji: '🌶️' },
  { id: 'dry-fruits', label: 'Dry Fruits', emoji: '🥜' },
  { id: 'chocolates', label: 'Chocolates', emoji: '🍫' },
];

const ShopPage = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState(searchParams.get('search') || '');
  const [category, setCategory] = useState(searchParams.get('category') || '');
  const [sidebarOpen, setSidebarOpen] = useState(false);

  const fetchProducts = (cat, q) => {
    setLoading(true);
    const params = { limit: 200 };
    if (cat) params.category = cat;
    if (q) params.search = q;
    productAPI.getAll(params)
      .then(res => { setProducts(res.data.products); setLoading(false); })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    const cat = searchParams.get('category') || '';
    const q = searchParams.get('search') || '';
    setCategory(cat);
    setSearch(q);
    fetchProducts(cat, q);
  }, [searchParams]);

  const handleSearch = (e) => {
    e.preventDefault();
    setSearchParams(prev => {
      if (search) prev.set('search', search); else prev.delete('search');
      prev.delete('category');
      return prev;
    });
  };

  const handleCategory = (cat) => {
    setSidebarOpen(false);
    setSearchParams(prev => {
      if (cat) prev.set('category', cat); else prev.delete('category');
      prev.delete('search');
      return prev;
    });
  };

  const catInfo = CATEGORIES.find(c => c.id === category);

  return (
    <div className="page-fade">
      {/* Header */}
      <div style={{ background: 'linear-gradient(135deg, var(--green), var(--green-dark))', color: 'white', padding: '24px 0 20px' }}>
        <div className="container">
          <h1 style={{ fontFamily: 'var(--font-display)', fontSize: 28, marginBottom: 14, display: 'flex', alignItems: 'center', gap: 10 }}>
            {catInfo ? `${catInfo.emoji} ${catInfo.label}` : '🛒 All Products'}
          </h1>
          <form onSubmit={handleSearch} style={{ display: 'flex', gap: 8, maxWidth: 500 }}>
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="🔍 Search products (e.g. mutton, carrot, honey...)"
              style={{ flex: 1, borderRadius: 10, border: 'none', padding: '12px 16px', fontSize: 15, boxShadow: 'none' }}
            />
            <button type="submit" style={{ background: 'var(--orange)', color: 'white', border: 'none', padding: '12px 20px', borderRadius: 10, fontWeight: 700, cursor: 'pointer', fontSize: 15, fontFamily: 'var(--font-display)' }}>
              Search
            </button>
          </form>
        </div>
      </div>

      <div className="container" style={{ padding: '24px 16px' }}>
        {/* Mobile filter toggle */}
        <button onClick={() => setSidebarOpen(!sidebarOpen)} style={{ display: 'none', background: 'var(--green)', color: 'white', border: 'none', borderRadius: 10, padding: '10px 18px', fontSize: 15, fontWeight: 700, cursor: 'pointer', marginBottom: 16, fontFamily: 'var(--font-display)' }}
          className="mobile-filter-btn">
          📋 {sidebarOpen ? 'Hide' : 'Show'} Categories
        </button>

        <style>{`.mobile-filter-btn { display: none } @media(max-width:768px) { .mobile-filter-btn { display: flex !important; } .shop-sidebar { display: ${sidebarOpen ? 'block' : 'none'} !important; margin-bottom: 16px !important; position: static !important; width: auto !important; } }`}</style>

        <div style={{ display: 'flex', gap: 24, alignItems: 'flex-start' }}>
          {/* Sidebar */}
          <div className="shop-sidebar" style={{ width: 210, flexShrink: 0, background: 'white', borderRadius: 18, padding: 16, boxShadow: '0 2px 10px rgba(0,0,0,0.06)', position: 'sticky', top: 80 }}>
            <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 17, color: 'var(--gray-800)', marginBottom: 12, paddingBottom: 8, borderBottom: '2px solid var(--green-bg)' }}>
              📋 Categories
            </h3>
            {CATEGORIES.map(cat => (
              <button key={cat.id} onClick={() => handleCategory(cat.id)}
                style={{ display: 'flex', alignItems: 'center', gap: 8, width: '100%', padding: '11px 12px', borderRadius: 12, border: 'none', cursor: 'pointer', marginBottom: 4, background: category === cat.id ? 'var(--green)' : 'transparent', color: category === cat.id ? 'white' : 'var(--gray-700)', fontWeight: category === cat.id ? 800 : 500, fontSize: 14, textAlign: 'left', transition: 'all 0.15s', fontFamily: 'var(--font-display)' }}
                onMouseEnter={e => { if (category !== cat.id) e.currentTarget.style.background = 'var(--green-bg)'; }}
                onMouseLeave={e => { if (category !== cat.id) e.currentTarget.style.background = 'transparent'; }}>
                <span style={{ fontSize: 18 }}>{cat.emoji}</span> {cat.label}
              </button>
            ))}
          </div>

          {/* Products Grid */}
          <div style={{ flex: 1 }}>
            {loading ? (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(190px, 1fr))', gap: 16 }}>
                {Array.from({ length: 12 }).map((_, i) => (
                  <div key={i} style={{ background: 'white', borderRadius: 16, height: 340, overflow: 'hidden', boxShadow: '0 2px 8px rgba(0,0,0,0.06)' }}>
                    <div className="skeleton" style={{ height: 160, borderRadius: 0 }} />
                    <div style={{ padding: 14, display: 'flex', flexDirection: 'column', gap: 8 }}>
                      <div className="skeleton" style={{ height: 12, width: '55%', borderRadius: 6 }} />
                      <div className="skeleton" style={{ height: 18, width: '80%', borderRadius: 6 }} />
                      <div className="skeleton" style={{ height: 12, width: '40%', borderRadius: 6 }} />
                      <div className="skeleton" style={{ height: 26, borderRadius: 6 }} />
                      <div className="skeleton" style={{ height: 38, borderRadius: 8 }} />
                    </div>
                  </div>
                ))}
              </div>
            ) : products.length === 0 ? (
              <div style={{ textAlign: 'center', padding: '60px 20px' }}>
                <div style={{ fontSize: 70 }}>🔍</div>
                <h3 style={{ fontFamily: 'var(--font-display)', fontSize: 22, color: 'var(--gray-500)', marginTop: 16 }}>No products found</h3>
                <p style={{ color: 'var(--gray-400)', marginTop: 8 }}>Try searching something else</p>
                <button onClick={() => handleCategory('')} style={{ background: 'var(--green)', color: 'white', border: 'none', borderRadius: 10, padding: '12px 24px', fontSize: 15, fontWeight: 700, cursor: 'pointer', marginTop: 20, fontFamily: 'var(--font-display)' }}>
                  View All Products
                </button>
              </div>
            ) : (
              <>
                <div style={{ marginBottom: 16, color: 'var(--gray-500)', fontSize: 14 }}>
                  Showing <strong style={{ color: 'var(--gray-800)' }}>{products.length}</strong> products
                  {category && ` in ${catInfo?.label}`}
                </div>
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(190px, 1fr))', gap: 16 }}>
                  {products.map(p => <ProductCard key={p._id} product={p} />)}
                </div>
              </>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShopPage;
